practice_tasks.solution:
def shortest_path(u, target, graph):
    if u == target: return (0, [u])
    best_dist, best_path = float('inf'), []
    for v in graph[u]:
        dist, path = shortest_path(v, target, graph)
        if graph[u][v] + dist < best_dist:
            best_dist = graph[u][v] + dist
            best_path = [u] + path
    return (best_dist, best_path)
